package io.github.chutian0610.jolt.bind;

import java.lang.reflect.Modifier;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.List;
import java.util.Map;

/**
 * The binding-layer classification of a target type, one home: every adapter answers "what
 * does this component bind as" through {@link #of} instead of maintaining its own if-chain —
 * the tree path ({@code BindValues}), the direct read ({@code DirectBinder}), and jolt-gen's
 * emitters and capability predicate all consume the one decision. Generation-time only:
 * nothing here is named by generated bytecode (the same discipline as {@link PojoSupport}).
 *
 * <p>The {@code java.*} exclusion is deliberately NOT a shape: a concrete JDK class binds as
 * a POJO on every read path (that is binding semantics); whether a type earns generated
 * bytecode is the capability predicate's call (jolt-gen), which layers its own exclusions on
 * top of a bindable shape. Exact {@link List}/{@link Map} raws classify as LIST/MAP for the
 * parameterized dispatch; a bare (unparameterized) raw is refused by each consumer with the
 * polymorphic message, exactly as when they fell through as interfaces.
 */
public enum BindingShape {
    TEXT, BOOLEAN, NUMBER, ENUM, RECORD, ARRAY, LIST, MAP, NATURAL, POJO, UNBOUND;

    /** The shape of a target's raw class: pure reference compares only — the adapters that
     * resolve plans once at construction keep their own caches; the tree path re-asks per
     * call, as it always has (zero allocation, fast-path order preserved). */
    public static BindingShape of(Class<?> raw) {
        if (raw == String.class) {
            return TEXT;
        }
        if (raw == boolean.class || raw == Boolean.class) {
            return BOOLEAN;
        }
        if (isNumber(raw)) {
            return NUMBER;
        }
        if (raw.isEnum()) {
            return ENUM;
        }
        if (raw.isRecord()) {
            return RECORD;
        }
        if (raw.isArray()) {
            return ARRAY;
        }
        if (raw == List.class) {
            return LIST;
        }
        if (raw == Map.class) {
            return MAP;
        }
        if (raw == Object.class) {
            return NATURAL;
        }
        if (!raw.isInterface() && !Modifier.isAbstract(raw.getModifiers())) {
            return POJO;
        }
        return UNBOUND;
    }

    /** The numeric widths, one definition: the six primitive forms, their boxes, and the
     * two exact types. (boolean is its own shape; String is TEXT.) */
    public static boolean isNumber(Class<?> raw) {
        return raw == byte.class || raw == Byte.class || raw == short.class || raw == Short.class
                || raw == int.class || raw == Integer.class || raw == long.class || raw == Long.class
                || raw == float.class || raw == Float.class || raw == double.class || raw == Double.class
                || raw == BigDecimal.class || raw == BigInteger.class;
    }

    /**
     * The integer-width bound, one table: the symmetric upper bound for byte/short/int/long
     * (primitive or box), {@code Long.MAX_VALUE} for the widest. The lower bound is always
     * {@code -bound - 1} (exact for all four widths: {@code -(2^63-1)-1 == Long.MIN_VALUE} in
     * long math) — the runtime checks and the generation-time emitters bake the same constant.
     * Non-integer widths throw: the callers have already classified via {@link #of}.
     */
    public static long longBoundMax(Class<?> raw) {
        if (raw == byte.class || raw == Byte.class) {
            return Byte.MAX_VALUE;
        }
        if (raw == short.class || raw == Short.class) {
            return Short.MAX_VALUE;
        }
        if (raw == int.class || raw == Integer.class) {
            return Integer.MAX_VALUE;
        }
        if (raw == long.class || raw == Long.class) {
            return Long.MAX_VALUE;
        }
        throw new IllegalArgumentException("no integer bound for " + raw.getSimpleName());
    }
}
